import shutil
import subprocess
from datetime import datetime

import pytest

from src.clinic.bookings import Booking
from src.clinic.confirmation import render_confirmation

pytestmark = pytest.mark.integration

BOOKING = Booking("Giulia Conti", "Dr Russo", datetime(2026, 10, 5, 9, 30))


def _pdf_text(pdf_bytes, tmp_path):
    path = tmp_path / "confirmation.pdf"
    path.write_bytes(pdf_bytes)
    if shutil.which("pdftotext"):
        result = subprocess.run(
            ["pdftotext", "-layout", str(path), "-"],
            capture_output=True,
            text=True,
            check=True,
        )
        return result.stdout

    # Keep the artifact check executable on development agents without
    # poppler-utils. This is a reader fallback, not a skipped PDF check.
    from pypdf import PdfReader

    reader = PdfReader(str(path), strict=True)
    return "\n".join(page.extract_text() or "" for page in reader.pages)


def test_confirmation_names_patient_and_time(tmp_path):
    text = _pdf_text(render_confirmation(BOOKING), tmp_path)
    assert "Giulia Conti" in text
    assert "Monday 5 October 2026, 09:30" in text


def test_confirmation_explains_how_to_cancel(tmp_path):
    text = _pdf_text(render_confirmation(BOOKING), tmp_path)
    assert "24 hours" in text


def _qpdf_check(pdf_bytes, tmp_path):
    path = tmp_path / "confirmation.pdf"
    path.write_bytes(pdf_bytes)
    if shutil.which("qpdf"):
        return subprocess.run(["qpdf", "--check", str(path)], capture_output=True, text=True)

    # pikepdf uses QPDF to parse the file. Reading every stream also catches
    # malformed stream data that opening the cross-reference table alone
    # would not exercise.
    try:
        import pikepdf

        with pikepdf.open(path) as pdf:
            for obj in pdf.objects:
                if obj.is_stream():
                    obj.read_bytes()
    except Exception as exc:
        return subprocess.CompletedProcess(
            ["pikepdf", "--check", str(path)],
            1,
            stdout="",
            stderr=f"{type(exc).__name__}: {exc}",
        )
    return subprocess.CompletedProcess(["pikepdf", "--check", str(path)], 0, stdout="", stderr="")


def test_confirmation_is_a_well_formed_pdf(tmp_path):
    result = _qpdf_check(render_confirmation(BOOKING), tmp_path)
    assert result.returncode == 0, result.stdout + result.stderr

